import { MakeLogicType, actions, afterMount, connect, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from '@posthog/lemon-ui'

import { projectLogic } from 'scenes/projectLogic'

import { cloudAgentsPresetsDestroy, cloudAgentsPresetsList } from '../generated/api'
import type { CloudAgentPresetApi } from '../generated/api.schemas'

const PRESETS_PAGE_SIZE = 200

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface cloudAgentPresetsLogicValues {
    currentProjectId: number | null // projectLogic
    deletingPresetId: string | null
    presets: CloudAgentPresetApi[] | null
    presetsLoadFailed: boolean
    presetsLoading: boolean
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface cloudAgentPresetsLogicActions {
    deletePreset: (preset: CloudAgentPresetApi) => {
        preset: CloudAgentPresetApi
    }
    deletePresetDone: () => {
        value: true
    }
    loadPresets: () => any
    loadPresetsFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadPresetsSuccess: (
        presets: CloudAgentPresetApi[],
        payload?: any
    ) => {
        presets: CloudAgentPresetApi[]
        payload?: any
    }
}

export type cloudAgentPresetsLogicType = MakeLogicType<cloudAgentPresetsLogicValues, cloudAgentPresetsLogicActions>

export const cloudAgentPresetsLogic = kea<cloudAgentPresetsLogicType>([
    path(['products', 'cloud_agents', 'frontend', 'logics', 'cloudAgentPresetsLogic']),
    connect(() => ({ values: [projectLogic, ['currentProjectId']] })),
    actions({
        deletePreset: (preset: CloudAgentPresetApi) => ({ preset }),
        deletePresetDone: true,
    }),
    loaders(({ values }) => ({
        presets: [
            null as CloudAgentPresetApi[] | null,
            {
                loadPresets: async (): Promise<CloudAgentPresetApi[]> => {
                    const response = await cloudAgentsPresetsList(String(values.currentProjectId), {
                        limit: PRESETS_PAGE_SIZE,
                    })
                    return response.results
                },
            },
        ],
    })),
    reducers({
        presetsLoadFailed: [false, { loadPresets: () => false, loadPresetsFailure: () => true }],
        deletingPresetId: [
            null as string | null,
            { deletePreset: (_, { preset }) => preset.id, deletePresetDone: () => null },
        ],
    }),
    listeners(({ actions, values }) => ({
        deletePreset: async ({ preset }) => {
            try {
                await cloudAgentsPresetsDestroy(String(values.currentProjectId), preset.id)
                lemonToast.success(`Deleted the preset "${preset.name}"`)
                actions.loadPresets()
            } catch {
                lemonToast.error(`Could not delete the preset "${preset.name}". Try again.`)
            } finally {
                actions.deletePresetDone()
            }
        },
    })),
    afterMount(({ actions }) => {
        actions.loadPresets()
    }),
])
